const $=s=>document.querySelector(s),screen=$('#screen');
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let roles=read('palais.roles',[{id:'rose',name:'玫瑰小姐',emoji:'🌷',prompt:'你是玫瑰小姐，一位温柔、细腻、有一点浪漫的朋友。用自然的中文与用户交流，认真倾听，不要总是使用华丽比喻。'},{id:'lune',name:'月光先生',emoji:'🌙',prompt:'你是月光先生，一位沉稳、体贴、幽默的朋友。用自然的中文聊天，回复简洁，尊重用户的感受。'}]);
let histories=read('palais.history',{}),config=read('palais.config',{base:'',model:'',key:'',remember:false}),key=config.remember?config.key||'':'',tab='home',current=null,busy=false,controller=null,editing=null;
const persist=()=>{localStorage.setItem('palais.roles',JSON.stringify(roles));localStorage.setItem('palais.history',JSON.stringify(histories))};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function time(){const t=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});$('#time').textContent=t;if($('#bigTime'))$('#bigTime').textContent=t}setInterval(time,1000);time();
function go(t){tab=t;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===t));render()}
function title(name,en,button=''){return `<div class="heading"><div><div class="eyebrow">${en}</div><h2>${name}</h2></div>${button}</div>`}
function render(){if(tab==='home'){screen.innerHTML=`<section class="home"><div class="crest">♔</div><div class="eyebrow">ROSE PALAIS</div><h2>玫瑰小宫殿</h2><div class="subtitle">你的私人浪漫宇宙</div><div class="clock" id="bigTime"></div><div class="date">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</div><div class="quote"><div class="flower">🌷</div><p>世界很大，<br>这里的温柔，只留给你。</p><small>A SOFT PLACE TO LAND</small></div><div class="apps"><button class="app" data-go="chat"><span>♡</span>聊天</button><button class="app" data-go="api"><span>⚙</span>API 设置</button><button class="app" data-go="book"><span>♧</span>世界书</button><button class="app" id="newHome"><span>＋</span>创建角色</button></div><div class="home-foot">Made of roses & little moments.</div></section>`;time();$('#newHome').onclick=()=>editRole()}else if(tab==='api'){renderApi()}else if(tab==='book'){renderBook()}else if(tab==='me'){renderMe()}else if(current){renderConversation()}else{screen.innerHTML=`<section class="view">${title('私语信箱','LET’S TALK, DEAR','<button class="round" id="newRole" aria-label="创建角色">+</button>')}<div class="notice">${config.base&&key&&config.model?'✧ API 已配置，选择一位角色开始聊天。':'先为小手机连接你的 API，开启第一段对话。 <button data-go="api">去设置 ↗</button>'}</div><div id="roleList"></div><p class="section-note">每一个角色，都是一段新的故事。<br>点右上角 ＋，创造属于你的相遇。</p></section>`;const list=$('#roleList');roles.forEach(r=>{const b=document.createElement('button');b.className='role';b.innerHTML=`${avatarHTML('role:'+r.id,r.emoji)}<div class="info"><strong>${escapeHtml(r.name)}</strong><p>${escapeHtml((histories[r.id]||[]).at(-1)?.content||'还没有说出口的故事，等你开启。')}</p></div><span class="arrow">›</span>`;b.onclick=()=>{current=r.id;render()};list.append(b)});$('#newRole').onclick=()=>editRole()}document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{current=null;go(b.dataset.go)})}
function editRole(id=null){editing=id;const r=roles.find(x=>x.id===id),f=$('#roleForm');f.reset();f.elements.namedItem('name').value=r?.name||'';f.emoji.value=r?.emoji||'🌷';f.prompt.value=r?.prompt||'';$('#editor h2').textContent=r?'编辑角色':'创建你的角色';roleAvatarDraft=mediaCache.get('role:'+id)||null;$('#roleAvatarPreview').innerHTML=roleAvatarDraft?`<span class="avatar"><img src="${roleAvatarDraft}" alt="角色头像预览"></span>`:avatarHTML('role:'+id,r?.emoji||'🌷');$('#roleAvatarFile').value='';$('#chooseRoleAvatar').onclick=()=>$('#roleAvatarFile').click();$('#roleAvatarFile').onchange=async e=>{const b=$('#chooseRoleAvatar'),save=$('#roleForm button[type="submit"]');b.disabled=true;save.disabled=true;try{roleAvatarDraft=await prepareImage(e.target.files[0]);$('#roleAvatarPreview').innerHTML=`<span class="avatar"><img src="${roleAvatarDraft}" alt="角色头像预览"></span>`}catch(err){toast(err.message)}finally{b.disabled=false;save.disabled=false;e.target.value=''}};$('#clearRoleAvatar').onclick=()=>{roleAvatarDraft=null;$('#roleAvatarPreview').innerHTML='<span class="avatar">'+escapeHtml(f.emoji.value||'🌷')+'</span>'};$('#editor').showModal()}
$('#cancelRole').onclick=()=>$('#editor').close();$('#roleForm').onsubmit=async e=>{e.preventDefault();const f=e.target;const name=f.elements.namedItem('name').value.trim(),prompt=f.prompt.value.trim();if(!name||!prompt)return;const r={id:editing||crypto.randomUUID(),name,emoji:f.emoji.value.trim()||'🌷',prompt};const oldRoles=roles;const save=f.querySelector('button[type="submit"]');save.disabled=true;try{await mediaWrite('role:'+r.id,roleAvatarDraft);roles=editing?roles.map(x=>x.id===editing?r:x):[...roles,r];persist();$('#editor').close();toast('角色已保存');go('chat')}catch(err){roles=oldRoles;toast(err.message||'保存失败，请重试')}finally{save.disabled=false}};
function renderApi(){screen.innerHTML=`<section class="view">${title('连接你的世界','API CONNECTION')}<div class="notice">支持 OpenAI 兼容接口。每位使用者填写自己的地址、密钥和模型。</div><form id="apiForm"><label>接口地址 · Base URL<input name="base" type="url" placeholder="https://你的接口域名/v1" required value="${escapeHtml(config.base)}"></label><label>API Key<input name="key" type="password" autocomplete="off" placeholder="填写你的 API 密钥" required value="${escapeHtml(key)}"></label><div class="model-setting"><div class="model-label">聊天模型<button class="text-button" type="button" id="loadModels">↻ 获取模型</button></div><input name="model" type="hidden" value="${escapeHtml(config.model)}"><select id="modelSelect" aria-label="选择聊天模型"><option value="${escapeHtml(config.model)}">${escapeHtml(config.model||'先点击「获取模型」')}</option></select><label id="modelManual" hidden>手动输入模型名称<input id="manualModelInput" placeholder="填写服务商提供的模型名称" value="${escapeHtml(config.model)}"></label><button class="text-button" type="button" id="manualModel">接口不支持列表？手动输入</button></div><label class="check"><input type="checkbox" name="remember" ${config.remember?'checked':''}>在此浏览器记住密钥（仅在自己的设备上开启）</label><div class="actions"><button class="secondary" type="button" id="testApi">测试连接</button><button class="primary">保存配置</button></div></form><div class="connection" id="connection" role="status"></div><p class="api-note">地址可填 /v1 或完整 /chat/completions 地址。请求从你的浏览器直接发送至所填接口，服务商需允许跨域访问（CORS）。密钥默认只留在当前页面内存中。</p></section>`;const apiForm=$('#apiForm');$('#loadModels').onclick=()=>loadModels(apiForm);$('#modelSelect').onchange=e=>{apiForm.model.value=e.target.value};$('#manualModelInput').oninput=e=>{apiForm.model.value=e.target.value.trim()};$('#manualModel').onclick=()=>{$('#modelSelect').hidden=true;$('#modelManual').hidden=false;$('#manualModelInput').value=apiForm.model.value;$('#manualModelInput').focus();$('#manualModel').hidden=true};const resetModels=()=>{$('#modelSelect').replaceChildren(new Option('接口已更改，请重新获取模型',''));apiForm.model.value='';$('#manualModelInput').value='';$('#modelSelect').hidden=false;$('#modelManual').hidden=true;$('#manualModel').hidden=false};apiForm.base.oninput=resetModels;apiForm.key.oninput=resetModels;$('#apiForm').onsubmit=e=>{e.preventDefault();if(!apiForm.model.value.trim()){toast('请先获取并选择模型，或手动输入');return}saveConfig(e.target);toast('API 配置已保存')};$('#testApi').onclick=async()=>{const f=$('#apiForm');if(!f.reportValidity())return;if(!f.model.value.trim()){toast('请先选择模型');return}const c=formConfig(f);const btn=$('#testApi'),status=$('#connection');btn.disabled=true;status.textContent='正在测试连接…';try{const result=await request(c,[{role:'user',content:'请只回复：连接成功'}],64);status.textContent='✓ 连接成功 · '+result.slice(0,80)}catch(err){status.textContent='连接失败：'+friendly(err)}finally{btn.disabled=false}}}
function formConfig(f){return {base:f.base.value.trim().replace(/\/+$/,''),key:f.key.value.trim(),model:f.model.value.trim(),remember:f.remember.checked}}
function saveConfig(f){const c=formConfig(f);key=c.key;config=c;localStorage.setItem('palais.config',JSON.stringify({...c,key:c.remember?key:''}))}
function endpoint(base){return PalaisCore.apiURL(base,'chat/completions')}
async function request(c,messages,max_tokens=1024,signal){const res=await fetch(endpoint(c.base),{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+c.key},body:JSON.stringify({model:c.model,messages,stream:false,max_tokens}),signal:signal||AbortSignal.timeout(45000)});let data;try{data=await res.json()}catch{throw Error('接口没有返回有效的 JSON（HTTP '+res.status+'）')}if(!res.ok)throw Error('HTTP '+res.status+' · '+(data.error?.message||'请求失败'));const content=data.choices?.[0]?.message?.content;if(typeof content!=='string'||!content.trim())throw Error('接口没有返回可用的回复，请检查模型与兼容格式');return content}
function friendly(err){if(err.name==='AbortError')return '已停止生成';if(err.name==='TimeoutError')return '连接超时，请稍后重试';if(err instanceof TypeError)return '无法访问接口，请检查地址、网络及服务商的 CORS 设置';return err.message}
function renderConversation(){const r=roles.find(x=>x.id===current);if(!r){current=null;render();return}screen.innerHTML=`<section class="chatview"><header class="chat-head"><button id="back" aria-label="返回聊天列表">‹</button>${avatarHTML('role:'+r.id,r.emoji)}<div class="identity">${escapeHtml(r.name)}<small>${busy?'正在回复…':'每一句话，都被好好珍藏'}</small></div><button id="editCurrent" aria-label="聊天装扮与角色设置">⋯</button></header><div class="messages" id="messages" aria-live="polite"></div><div id="chatError" role="status"></div><form class="composer" id="composer"><textarea rows="1" placeholder="写下想对 TA 说的话…" aria-label="聊天消息" ${busy?'disabled':''}></textarea><button class="primary" aria-label="${busy?'停止生成':'发送消息'}" type="${busy?'button':'submit'}" id="send">${busy?'■':'↑'}</button></form></section>`;$('#back').onclick=()=>{current=null;render()};$('#editCurrent').onclick=()=>openAppearance(r);const history=histories[r.id]||[],messages=$('#messages');const background=mediaCache.get('background:'+r.id);if(background){messages.classList.add('custom-background');messages.style.backgroundImage=`linear-gradient(#fffaf530,#fffaf530),url("${background}")`};messages.innerHTML=history.length?'<div class="conversation-date">你们的私语时光</div>':`<div class="empty-chat"><span>${escapeHtml(r.emoji)}</span>你好，我是${escapeHtml(r.name)}。<br>从一句「你好」开始吧。<br><small>${config.base&&key&&config.model?'':'聊天前，记得在 API 设置中连接你的接口。'}</small></div>`;history.forEach(m=>{const el=document.createElement('div');el.className='msg '+m.role;el.innerHTML=(m.role==='assistant'?avatarHTML('role:'+r.id,r.emoji):avatarHTML('profile','🎀'))+`<div class="bubble">${escapeHtml(m.content)}</div>`;messages.append(el)});if(busy){const el=document.createElement('div');el.className='msg';el.innerHTML='<div class="bubble">正在酝酿一句温柔…</div>';messages.append(el)}messages.scrollTop=messages.scrollHeight;$('#composer').onsubmit=e=>{e.preventDefault();sendMessage(r,$('#composer textarea').value.trim())};$('#composer textarea').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#composer').requestSubmit()}};if(busy)$('#send').onclick=()=>controller?.abort()}
async function sendMessage(r,value){if(!value||busy)return;if(!config.base||!key||!config.model){toast('请先配置 API 地址、密钥与模型');current=null;go('api');return}const id=r.id;const hist=histories[id]||(histories[id]=[]);hist.push({role:'user',content:value});persist();busy=true;controller=new AbortController();const timer=setTimeout(()=>controller?.abort(),60000);render();try{const reply=await request({...config,key},[{role:'system',content:PalaisCore.systemPrompt(r,worldbook,hist)},...hist.slice(-40)],1024,controller.signal);hist.push({role:'assistant',content:reply});persist()}catch(err){const message=friendly(err);toast(message);if(tab==='chat'&&current===id){busy=false;render();$('#chatError').className='error';$('#chatError').textContent=message+'。可以重新发送消息。'}return}finally{clearTimeout(timer);busy=false;controller=null}render()}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderMe(){const count=Object.values(histories).reduce((n,a)=>n+a.length,0);screen.innerHTML=`<section class="view">${title('我的小宫殿','A WORLD OF YOUR OWN')}<div class="profile-card">${avatarHTML('profile','🎀')}<h3>${escapeHtml(profile.name)}</h3><button class="text-button" id="editProfile">编辑人物与头像 ↗</button><p>今天，也要把温柔留一点给自己。</p></div><div class="stats"><div><strong>${roles.length}</strong>位角色</div><div><strong>${count}</strong>条私语</div></div><button class="menu-button" id="exportData">导出角色、聊天与世界书 <span>↗</span></button><button class="menu-button" data-go="book">世界书 <span>›</span></button><button class="menu-button" data-go="api">管理 API 配置 <span>›</span></button><button class="menu-button" id="clearKey">清除保存的 API 密钥 <span>×</span></button><p class="section-note">记录仅保存在当前浏览器，暂不跨设备同步。<br>导出文件不包含 API 密钥。<br>ROSE PALAIS · 私人小宫殿</p></section>`;$('#exportData').onclick=()=>download('玫瑰小宫殿-聊天备份.json',{roles,histories,worldbook,profile,images:Object.fromEntries(mediaCache),exportedAt:new Date().toISOString()});$('#editProfile').onclick=renderProfile;$('#clearKey').onclick=()=>{key='';config.key='';config.remember=false;localStorage.setItem('palais.config',JSON.stringify(config));toast('API 密钥已清除')}}
async function share(){try{await navigator.clipboard.writeText(location.origin+location.pathname);toast('私人链接已复制，目前仅你能访问')}catch{toast('可复制浏览器地址栏中的链接分享')}}
$('#share').onclick=share;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.tab==='chat')current=null;go(b.dataset.tab)});render();
